{"request":{"publicParam":[{"requestName":"method","mustNeed":true,"type":2,"style":1,"example":"token.create","description":"调用的API接口名称"},{"requestName":"app_key","mustNeed":true,"type":2,"style":1,"example":"6839996111118329223","description":"应用创建完成后被分配的key"},{"requestName":"param_json","mustNeed":true,"type":2,"style":1,"example":"{cid:12,page:1}","description":"标准json类型，里面是业务参数按照参数名的字符串大小排序具体参数值，参考每个接口的参数表"},{"requestName":"timestamp","mustNeed":true,"type":2,"style":1,"example":"2020-09-15 14:48:13","description":"时间戳，格式为yyyy-MM-dd HH:mm:ss，时区为GMT+8，例如：2016-01-01 12:00:00"},{"requestName":"v","mustNeed":true,"type":2,"style":1,"example":"2","description":"API协议版本，当前版本为2"},{"requestName":"sign","mustNeed":true,"type":2,"style":1,"example":"796559d40beb08a1a1113c456c5c5a62","description":"输入参数签名结果，签名算法参照 [API调用指南](https://op.jinritemai.com/docs/guide-docs/10/23)"},{"requestName":"sign_method","mustNeed":false,"type":2,"style":1,"example":"hmac-sha256","description":"签名算法类型推荐使用hmac-sha256后续会下线md5（不传则默认为"md5"）1. md5:表示用md5算法加密字符串 2. hmac-sha256:表示用hmac_sha_256算法加密字符串"}],"requestParam":[{"requestName":"code","toName":"code","mustNeed":false,"type":2,"style":1,"example":"82bdc687-eff1-4f63-8444-0b43086c25fd","description":"授权码；参数必传，工具型应用: 传code值；自用型应用:传""","cipherTextType":1},{"requestName":"grant_type","toName":"grantType","mustNeed":true,"type":2,"style":1,"example":"authorization_code","description":"授权类型 ；【工具型应用:authorization_code  自用型应用:authorization_self】，如果自用型应用有授权code，传authorization_code","cipherTextType":1},{"requestName":"test_shop","toName":"testShop","mustNeed":false,"type":2,"style":1,"example":"2","description":"判断测试店铺标识 ，非必传，若新增测试店铺传1，若不是则不必传","cipherTextType":1},{"requestName":"shop_id","toName":"shopId","mustNeed":false,"type":2,"style":1,"example":"17239","description":"店铺ID，抖店自研应用使用。当auth_subject_type不为空时，该字段请勿传值，请将值传入到auth_id字段中","cipherTextType":1},{"requestName":"auth_id","toName":"authId","mustNeed":false,"type":2,"style":1,"example":"112334",